ee:message.ee:set-payload:
%dw 2.0
output application/json
var billingData = vars.billingResponsePayload.primaryAccount

//if policyTerm is array we are checking for the object which has other fields as well apart from just version
var policyVersion = if(billingData.policies.policyTerm is Object) billingData.policies.policyTerm.version else ((billingData.policies.policyTerm filter (item) -> sizeOf(keysOf(item)) > 1)[0].version)

// if policyTerm is array we filter the array for the object with the same version value
var transactions = 
    if (billingData.policies.policyTerm is Object) 
        billingData.policies.policyTerm.escrowAccount.transactions default [] 
    else 
        ((billingData.policies.policyTerm filter (item) -> item.version == policyVersion)[0].escrowAccount.transactions default [])

---
{
    "policyNumber":billingData.accountNumber,
    "policyVersion":policyVersion,
    "escrowTransactions":transactions
}
